static inline const char *GetFormSuffix(uint16_t speciesId, uint8_t formIndex)
{
    switch (speciesId) {
    case 386:
        switch (formIndex) {
        case 1: return "-Attack";
        case 2: return "-Defense";
        case 3: return "-Speed";
        default: return "";
        }
    case 412:
        switch (formIndex) {
        case 1: return "-Sandy";
        case 2: return "-Trash";
        default: return "";
        }
    case 413:
        switch (formIndex) {
        case 1: return "-Sandy";
        case 2: return "-Trash";
        default: return "";
        }
    case 479:
        switch (formIndex) {
        case 1: return "-Heat";
        case 2: return "-Wash";
        case 3: return "-Frost";
        case 4: return "-Fan";
        case 5: return "-Mow";
        default: return "";
        }
    case 487:
        switch (formIndex) {
        case 1: return "-Origin";
        default: return "";
        }
    case 492:
        switch (formIndex) {
        case 1: return "-Sky";
        default: return "";
        }
    default:
        return "";
    }
}

